,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>unistr('/* T\00EDtulo (Habilidade) em rosa */ .t-Card-title {     color: #E91E63 !important;     font-weight: 600 !important;     font-size: 1.1rem !important; }  /* Todas as imagens com tamanho fixo e uniforme */ .t-Card-icon img, .t-Card-media img {     width:')
