||';     display: flex !important;     align-items: center !important;     justify-content: center !important;     background-color: #f8f9fa !important; }'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>20
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ID,',
'       HABILIDADE,',
'       NIVEL,',
'       ''#APP_IMAGES#'' || ',
'       CASE ',
'           WHEN LOWER(HABILIDADE) = ''java'' THEN ''Java.png''',
'           WHEN LOWER(HABILIDADE) = ''html'' THEN ''html.png''',
'           WHEN LOWER(HABILIDADE) = ''sql'' THEN ''sql.png''',
'           WHEN LOWER(HABILIDADE) = ''figma'' THEN ''Figma.png''',
'           WHEN LOWER(HABILIDADE) = ''javascript'' THEN ''JavaScript.png''',
'           WHEN LOWER(HABILIDADE) = ''bootstrap'' THEN ''bootstrap.jpg''',
'           WHEN LOWER(HABILIDADE) = ''canva'' THEN ''canva.png''',
'           WHEN LOWER(HABILIDADE) = ''css'' THEN ''css.png''',
'           WHEN LOWER(HABILIDADE) = ''oracle apex'' THEN ''apex.png''',
unistr('           WHEN LOWER(HABILIDADE) = ''manuten\00E7\00E3o b\00E1sica de computadores'' THEN ''manutencao.png'''),
'           WHEN LOWER(HABILIDADE) = ''react / react native'' THEN ''react.png''',
'           WHEN LOWER(HABILIDADE) = ''excel'' THEN ''Excel.png''',
'           WHEN LOWER(HABILIDADE) = ''git/github'' THEN ''GIT.png''',
'           WHEN LOWER(HABILIDADE) = ''node.js'' THEN ''node.js.png''',
